import asyncio


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently, returning results in input order.
    Any coroutine not finishing within `seconds` is cancelled and its result is None.
    Can be called repeatedly from synchronous code with no running event loop."""
    async def _run_all_with_deadline():
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=seconds)
        # Cancel all pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion
        for task in pending:
            try:
                await task
            except asyncio.CancelledError:
                pass
            except Exception:
                pass  # ignore exceptions from cancelled tasks
        # Collect results in input order
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    # If a task raised, propagate the exception
                    raise
            else:
                results.append(None)
        return results

    loop = asyncio.new_event_loop()
    try:
        return loop.run_until_complete(_run_all_with_deadline())
    finally:
        loop.close()

